#include <stdint.h>

typedef void (*thk_pick_int_cb)(int64_t ctx, int32_t value);

/* --- picking ----------------------------------------------------------------- */
/* Shows the photo picker for up to `limit` images: PHPickerViewController (iOS), an
   NSOpenPanel sheet for images (macOS). Returns 1, or 0 with nothing shown and nothing
   called when there is no window to show it over or a picker is already up. */
