/* Shows the document picker for `types`, MIME types separated by newlines ("" for any):
   UIDocumentPickerViewController(forOpeningContentTypes:asCopy: true) on iOS, an NSOpenPanel
   sheet on macOS. `multiple` 1 lets the user choose several. Returns as thk_pick_photos. */
int32_t thk_pick_documents(const char *types, int32_t multiple, thk_pick_int_cb file,
                           thk_pick_int_cb done, int64_t ctx);
/* The file a hold is for: a path, valid until thk_pick_release. NULL for an unknown hold. */
const char *thk_pick_path(int32_t hold);
/* Where the hold's file stands in the user's selection, from 0; -1 for an unknown hold. */
