void thk_pick_release(int32_t hold);
/* Asks where to save `file`, which Scala wrote under the suggested name. iOS:
   UIDocumentPickerViewController(forExporting:asCopy: true), which copies it itself. macOS: an
   NSSavePanel sheet suggesting its name, of the type of `mime`. `answered` on the main thread:
   0 cancelled, 1 the system saved it, 2 the user chose a destination, which
   thk_pick_save_path gives inside the call, for Scala to write. Returns as thk_pick_photos. */
int32_t thk_pick_save(const char *file, const char *mime, thk_pick_int_cb answered, int64_t ctx);
/* The destination chosen in the latest save, valid inside `answered`; NULL if none. */
const char *thk_pick_save_path(void);

/* --- testing ----------------------------------------------------------------- */
